// The Undercroft: a buried factory under the Scrapyard, reached by the hatch
// in the sentry ruins. Dark (see world.json). Rooms:
//   Entry (ladder up), crawler hall, sorting room (north-east),
//   the foundry floor (a level down), the antechamber and the press hall
//   (the Splatterpress's arena, zone "arena", behind its door), and the
//   warden's vault (a level up) with the sealed vault holding the blueprint.

name: The Undercroft
spawn: none
ground: foundry
zone arena: 2,26 14,34

[legend]
8  terrain foundry_wall
.  floor
u  station undercroft_ladder
x  node foundry_cache
,  decor scrap_pile
<  decor console
!  decor blue_lamp
-  decor cable
*  decor lamp
k  npc scrap_crawler
y  npc foundry_drone
>  decor conveyor
+  decor crate
$  decor sign
(  decor barrel
_  decor pipe
